enum class AckCheckResult {
    
    /**
     * Definitely a duplicate — found in the in-memory cache.
     */
    IN_CACHE,
    /**
     * Not in cache; caller must query the persistent store before deciding.
     */
    NEED_DB_CHECK,
    /**
     * Confirmed not a duplicate (after DB check returned nothing).
     */
    NOT_PROCESSED;
    companion object
}


/**
 * @suppress
 */
public object FfiConverterTypeAckCheckResult: FfiConverterRustBuffer<AckCheckResult> {
    override fun read(buf: ByteBuffer) = try {
        AckCheckResult.values()[buf.getInt() - 1]
    } catch (e: IndexOutOfBoundsException) {
        throw RuntimeException("invalid enum value, something is very wrong!!", e)
    }

    override fun allocationSize(value: AckCheckResult) = 4UL

    override fun write(value: AckCheckResult, buf: ByteBuffer) {
        buf.putInt(value.ordinal + 1)
    }
}





/**
 * Typed replacement for `Action` JSON strings.
 * Platform receives these from `handle_event()` and executes each one.
 */
sealed class CfeAction {
    
    data class DecryptMessage(
        val `contactId`: kotlin.String, 
        val `ciphertext`: kotlin.ByteArray) : CfeAction()
        
    {
        

        companion object
    }
    
    data class EncryptMessage(
        val `contactId`: kotlin.String, 
        val `plaintext`: kotlin.ByteArray) : CfeAction()
        
    {
        

        companion object
    }
    
    data class InitSession(
        val `contactId`: kotlin.String, 
        val `bundleJson`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    data class ArchiveSession(
        val `contactId`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    data class MessageDecrypted(
        val `contactId`: kotlin.String, 
        val `messageId`: kotlin.String, 
        val `plaintext`: kotlin.ByteArray) : CfeAction()
        
    {
        

        companion object
    }
    
    data class PendingDropped(
        val `contactId`: kotlin.String, 
        val `messageIds`: List<kotlin.String>) : CfeAction()
        
    {
        

        companion object
    }
    
    /**
     * END_SESSION suppressed by cooldown — the core owes it and sends it in retry_after_ms.
     * Platform must NOT ACK.
     */
    data class EndSessionSuppressed(
        val `contactId`: kotlin.String, 
        val `retryAfterMs`: kotlin.ULong) : CfeAction()
        
    {
        

        companion object
    }
    
    /**
     * A teardown was asked for and will not be sent, now or later — the peer tore this ratchet
     * down itself. Nothing is owed; do NOT schedule a retry.
     */
    data class EndSessionNotNeeded(
        val `contactId`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    /**
     * Open a new session with `contact_id` as INITIATOR over the one held: build it with
     * `reopen_session`, which keeps the held state as a previous one. Nothing is sent for it —
     * the handshake header rides on the next message. Raised by the PQXDH v2 upgrade sweep.
     */
    data class OpenSession(
        val `contactId`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    /**
     * Message queued inside the core behind an in-flight session init. Nothing lost.
     */
    data class MessageQueuedPendingInit(
        val `contactId`: kotlin.String, 
        val `queuedCount`: kotlin.UInt) : CfeAction()
        
    {
        

        companion object
    }
    
    /**
     * Write `data` into `slot`; empty `data` is a delete sentinel where the slot says so.
     */
    data class SaveToSecureStore(
        val `slot`: CfeSecureStoreSlot, 
        val `data`: kotlin.ByteArray) : CfeAction()
        
    {
        

        companion object
    }
    
    data class PersistAck(
        val `messageId`: kotlin.String, 
        val `timestamp`: kotlin.ULong) : CfeAction()
        
    {
        

        companion object
    }
    
    data class PruneAckStore(
        val `cutoffTs`: kotlin.ULong) : CfeAction()
        
    {
        

        companion object
    }
    
    data class MarkMessageDelivered(
        val `messageId`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    /**
     * A message already handled (ACK cache, platform DB, or its ratchet key already used).
     * Terminal: record it as processed and advance the stream cursor past it.
     */
    data class DuplicateDropped(
        val `messageId`: kotlin.String) : CfeAction()
        
    {
        

        companion object
    }
    
    data class OpenReceiving(
        val `contactId`: kotlin.String) : CfeAction()
        
    {
        

