/**
 * Typed replacement for `IncomingEvent` JSON strings.
 * Platform creates one of these variants and passes to `handle_event()`.
 */
sealed class CfeIncomingEvent {
    
    data class MessageReceived(
        val `messageId`: kotlin.String, 
        val `from`: kotlin.String, 
        val `data`: kotlin.ByteArray, 
        val `msgNum`: kotlin.UInt, 
        val `kemCt`: kotlin.ByteArray, 
        val `otpkId`: kotlin.UInt, 
        val `isControl`: kotlin.Boolean, 
        val `contentType`: kotlin.UByte, 
        val `senderCertificate`: SenderCertificate?) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    data class OutgoingMessage(
        val `contactId`: kotlin.String, 
        val `messageId`: kotlin.String, 
        val `plaintext`: kotlin.ByteArray, 
        val `contentType`: kotlin.UByte) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    data class OutgoingCallSignal(
        val `contactId`: kotlin.String, 
        val `messageId`: kotlin.String, 
        val `protoBytes`: kotlin.ByteArray) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    data class SessionInitCompleted(
        val `contactId`: kotlin.String, 
        val `sessionData`: kotlin.ByteArray) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    data class AckReceived(
        val `messageId`: kotlin.String) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    data class KeyBundleFetched(
        val `userId`: kotlin.String, 
        val `bundleJson`: kotlin.String) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    object NetworkReconnected : CfeIncomingEvent()
    
    
    object AppLaunched : CfeIncomingEvent()
    
    
    data class TimerFired(
        val `timerId`: kotlin.String) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    /**
     * Platform ACK DB lookup result — response to `CheckAckInDb` action.
     */
    data class AckDbResult(
        val `messageId`: kotlin.String, 
        val `isProcessed`: kotlin.Boolean) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    /**
     * A heartbeat message was received from the peer.
     */
    data class HeartbeatReceived(
        val `contactId`: kotlin.String, 
        val `messageId`: kotlin.String, 
        val `data`: kotlin.ByteArray, 
        val `msgNum`: kotlin.UInt) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    /**
     * The platform is about to tear down the ratchet with `contact_id` and asks whether it may.
     * Answered with `SendEndSession`, `EndSessionSuppressed` + `ScheduleTimer`, or
     * `EndSessionNotNeeded` — from the same window the core's own teardowns use. `cause` says
     * what this teardown knows, which decides how soon it may go and whether the peer's own
     * teardown silences it.
     */
    data class TeardownRequested(
        val `contactId`: kotlin.String, 
        val `cause`: CfeTearDownCause) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    
    /**
     * The peer tore down the ratchet with `contact_id` and the platform has applied it. A
     * report, not a request: it opens the window that keeps our own teardown quiet, and returns
     * no actions.
     */
    data class PeerToreDown(
        val `contactId`: kotlin.String) : CfeIncomingEvent()
        
    {
        

        companion object
    }
    

    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeCfeIncomingEvent : FfiConverterRustBuffer<CfeIncomingEvent>{
    override fun read(buf: ByteBuffer): CfeIncomingEvent {
        return when(buf.getInt()) {
            1 -> CfeIncomingEvent.MessageReceived(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterUInt.read(buf),
                FfiConverterBoolean.read(buf),
                FfiConverterUByte.read(buf),
                FfiConverterOptionalTypeSenderCertificate.read(buf),
                )
            2 -> CfeIncomingEvent.OutgoingMessage(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterUByte.read(buf),
                )
            3 -> CfeIncomingEvent.OutgoingCallSignal(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                )
            4 -> CfeIncomingEvent.SessionInitCompleted(
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                )
            5 -> CfeIncomingEvent.AckReceived(
                FfiConverterString.read(buf),
                )
            6 -> CfeIncomingEvent.KeyBundleFetched(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                )
            7 -> CfeIncomingEvent.NetworkReconnected
            8 -> CfeIncomingEvent.AppLaunched
            9 -> CfeIncomingEvent.TimerFired(
                FfiConverterString.read(buf),
                )
            10 -> CfeIncomingEvent.AckDbResult(
                FfiConverterString.read(buf),
                FfiConverterBoolean.read(buf),
                )
            11 -> CfeIncomingEvent.HeartbeatReceived(
                FfiConverterString.read(buf),
                FfiConverterString.read(buf),
                FfiConverterByteArray.read(buf),
                FfiConverterUInt.read(buf),
                )
            12 -> CfeIncomingEvent.TeardownRequested(
                FfiConverterString.read(buf),
                FfiConverterTypeCfeTearDownCause.read(buf),
                )
            13 -> CfeIncomingEvent.PeerToreDown(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
